arguments.cmd:
cd /app && cat > output/styles.css <<'CSS'
:root {
  /* Core palette (cinematic dark) */
  --bg: #141414;
  --bg-2: #0b0b0b;
  --panel: rgba(255, 255, 255, 0.06);
  --panel-2: rgba(255, 255, 255, 0.09);
  --text: rgba(255, 255, 255, 0.94);
  --muted: rgba(255, 255, 255, 0.72);
  --muted-2: rgba(255, 255, 255, 0.58);
  --border: rgba(255, 255, 255, 0.12);

  --brand: #e50914;
  --brand-2: #ff2a2a;

  --shadow: 0 18px 40px rgba(0, 0, 0, 0.45);
  --radius-xl: 22px;
  --radius-lg: 16px;
  --radius-md: 12px;

  --max: 1160px;

  --font-sans: Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji",
    "Segoe UI Emoji";
  --font-display: "Bebas Neue", Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  background: radial-gradient(1200px 700px at 50% -120px, rgba(229, 9, 20, 0.15), transparent 55%),
    radial-gradient(900px 600px at 0% 0%, rgba(255, 255, 255, 0.06), transparent 50%),
    var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  margin: 0;
}

a { color: inherit; text-decoration: none; }

.container {
  width: min(var(--max), calc(100% - 40px));
  margin: 0 auto;
}

@media (max-width: 480px) {
  .container { width: calc(100% - 28px); }
}

/* Accessibility */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

:focus-visible {
  outline: 3px solid rgba(229, 9, 20, 0.6);
  outline-offset: 3px;
  border-radius: 10px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 1px solid transparent;
  border-radius: 999px;
  padding: 12px 18px;
  font-weight: 700;
  letter-spacing: 0.2px;
  cursor: pointer;
  transition: transform 140ms ease, box-shadow 180ms ease, background 180ms ease, border-color 180ms ease;
  user-select: none;
}

.btn:active { transform: scale(0.98); }

.btn-primary {
  background: linear-gradient(180deg, var(--brand-2), var(--brand));
  color: white;
  box-shadow: 0 14px 30px rgba(229, 9, 20, 0.22);
}

.btn-primary:hover {
  box-shadow: 0 18px 40px rgba(229, 9, 20, 0.28);
  transform: translateY(-1px);
}

.btn-ghost {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.14);
  color: var(--text);
}

.btn-ghost:hover {
  background: rgba(255, 255, 255, 0.09);
  border-color: rgba(255, 255, 255, 0.18);
}

/* Form */
.field {
  display: grid;
  gap: 8px;
}

.label {
  font-size: 0.9rem;
  color: var(--muted);
}

.input {
  width: 100%;
  background: rgba(0, 0, 0, 0.35);
  color: var(--text);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 14px;
  padding: 14px 14px;
  transition: border-color 160ms ease, background 160ms ease;
}

.input::placeholder { color: rgba(255, 255, 255, 0.45); }

.input:focus {
  outline: none;
  border-color: rgba(229, 9, 20, 0.55);
  background: rgba(0, 0, 0, 0.5);
}

.input-error {
  border-color: rgba(255, 77, 77, 0.7);
}

.hint {
  color: rgba(255, 120, 120, 0.85);
  font-size: 0.9rem;
}

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 30;
  background: linear-gradient(180deg, rgba(20, 20, 20, 0.92), rgba(20, 20, 20, 0.65));
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 0;
  gap: 14px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 900;
  letter-spacing: 0.2px;
}

.brand-mark {
  width: 26px;
  height: 18px;
  border-radius: 6px;
  background: linear-gradient(180deg, var(--brand-2), var(--brand));
  box-shadow: 0 12px 26px rgba(229, 9, 20, 0.22);
  position: relative;
}

.brand-mark::after {
  content: "";
  position: absolute;
  left: 6px;
  top: 4px;
  width: 0;
  height: 0;
  border-top: 5px solid transparent;
  border-bottom: 5px solid transparent;
  border-left: 8px solid rgba(255, 255, 255, 0.92);
}

.brand-name {
  font-family: var(--font-display);
  font-size: 1.55rem;
  letter-spacing: 1px;
}

.nav-actions {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.select {
  appearance: none;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 999px;
  padding: 10px 34px 10px 12px;
  color: var(--text);
  font-weight: 650;
  cursor: pointer;
}

.select-wrap {
  position: relative;
}

.select-wrap::after {
  content: "▾";
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(255, 255, 255, 0.75);
  pointer-events: none;
  font-size: 0.9rem;
}

@media (max-width: 560px) {
  .select-wrap { display: none; }
}

/* Hero */
.hero {
  padding: 54px 0 28px;
}

.hero-shell {
  position: relative;
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(900px 500px at 70% 30%, rgba(229, 9, 20, 0.22), transparent 58%),
    radial-gradient(800px 520px at 20% 20%, rgba(255, 255, 255, 0.08), transparent 55%),
    linear-gradient(180deg, rgba(0, 0, 0, 0.35), rgba(0, 0, 0, 0.85)),
    url("https://images.unsplash.com/photo-1524985069026-dd778a71c7b4?auto=format&fit=crop&w=2400&q=70");
  background-size: cover;
  background-position: center;
  filter: saturate(1.05) contrast(1.05);
}

.hero-grid {
  position: relative;
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 22px;
  padding: 34px;
  align-items: center;
}

@media (max-width: 920px) {
  .hero-grid { grid-template-columns: 1fr; padding: 24px; }
}

.hero-kicker {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: rgba(0, 0, 0, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.12);
  padding: 8px 12px;
  border-radius: 999px;
  color: rgba(255, 255, 255, 0.88);
  width: fit-content;
}

.pill-dot {
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: var(--brand);
  box-shadow: 0 0 0 4px rgba(229, 9, 20, 0.15);
}

.hero h1 {
  font-family: var(--font-display);
  font-size: clamp(2.25rem, 5vw, 4.1rem);
  line-height: 0.95;
  letter-spacing: 0.5px;
  margin: 14px 0 10px;
}

.hero-sub {
  font-size: 1.12rem;
  color: rgba(255, 255, 255, 0.86);
  margin: 0 0 12px;
}

.hero-prompt {
  color: rgba(255, 255, 255, 0.8);
  margin: 0 0 14px;
}

.hero-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  align-items: center;
}

@media (max-width: 520px) {
  .hero-form { grid-template-columns: 1fr; }
  .hero-form .btn { width: 100%; }
}

.mini-note {
  margin-top: 10px;
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.92rem;
}

/* Right hero panel */
.hero-panel {
  background: rgba(0, 0, 0, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: var(--radius-lg);
  padding: 18px;
}

.hero-panel-title {
  font-weight: 800;
  letter-spacing: 0.2px;
  margin: 0 0 12px;
}

.stat-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px 14px;
  padding: 12px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.stat-row:first-of-type { border-top: none; padding-top: 0; }

.stat-label { color: rgba(255, 255, 255, 0.75); }
.stat-value { font-weight: 850; }

.badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(229, 9, 20, 0.12);
  border: 1px solid rgba(229, 9, 20, 0.28);
  padding: 8px 10px;
  border-radius: 999px;
  font-weight: 800;
  color: rgba(255, 255, 255, 0.92);
  margin-top: 12px;
}

/* Section */
.section {
  padding: 42px 0;
}

.section-title {
  font-family: var(--font-display);
  letter-spacing: 0.8px;
  font-size: clamp(1.7rem, 3vw, 2.45rem);
  margin: 0 0 16px;
}

.section-sub {
  margin: 0 0 18px;
  color: var(--muted);
}

/* Trending carousel */
.carousel {
  position: relative;
}

.carousel-viewport {
  display: flex;
  gap: 14px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding: 6px 2px 10px;
  scrollbar-width: none;
}

.carousel-viewport::-webkit-scrollbar { display: none; }

.card {
  scroll-snap-align: start;
  flex: 0 0 auto;
  width: 210px;
  border-radius: 18px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.06);
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.35);
  position: relative;
}

@media (max-width: 480px) {
  .card { width: 165px; }
}

.poster {
  height: 300px;
  background-size: cover;
  background-position: center;
  position: relative;
}

@media (max-width: 480px) {
  .poster { height: 248px; }
}

.poster::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(340px 220px at 50% 10%, rgba(255, 255, 255, 0.08), transparent 55%),
    linear-gradient(180deg, rgba(0, 0, 0, 0.05), rgba(0, 0, 0, 0.82));
}

.rank {
  position: absolute;
  left: 10px;
  bottom: 56px;
  font-family: var(--font-display);
  font-size: 5.2rem;
  letter-spacing: 1px;
  color: rgba(255, 255, 255, 0.16);
  text-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
  pointer-events: none;
}

.card-body {
  padding: 12px 12px 14px;
  position: relative;
}

.card-title {
  font-weight: 850;
  letter-spacing: 0.2px;
  margin: 0;
}

.card-meta {
  margin: 6px 0 0;
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.92rem;
}

.carousel-controls {
  position: absolute;
  right: 0;
  top: -54px;
  display: flex;
  gap: 10px;
}

.icon-btn {
  width: 44px;
  height: 44px;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(0, 0, 0, 0.35);
  color: rgba(255, 255, 255, 0.92);
  cursor: pointer;
  transition: transform 140ms ease, background 160ms ease, border-color 160ms ease;
}

.icon-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.2);
  transform: translateY(-1px);
}

.icon {
  width: 18px;
  height: 18px;
  display: block;
}

/* Features */
.features {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

@media (max-width: 980px) {
  .features { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 560px) {
  .features { grid-template-columns: 1fr; }
}

.feature-card {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.05));
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 18px;
  padding: 18px;
  min-height: 190px;
  position: relative;
  overflow: hidden;
}

.feature-card::before {
  content: "";
  position: absolute;
  inset: -40px -40px auto auto;
  width: 120px;
  height: 120px;
  background: radial-gradient(circle at 30% 30%, rgba(229, 9, 20, 0.26), transparent 60%);
  transform: rotate(20deg);
}

.feature-title {
  font-weight: 900;
  margin: 0 0 8px;
}

.feature-desc {
  margin: 0;
  color: rgba(255, 255, 255, 0.74);
  line-height: 1.5;
}

.feature-icon {
  position: absolute;
  right: 14px;
  bottom: 14px;
  width: 44px;
  height: 44px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: rgba(0, 0, 0, 0.38);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

/* FAQ */
.faq {
  display: grid;
  gap: 12px;
}

.faq-item {
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.06);
  overflow: clip;
}

.faq-q {
  width: 100%;
  text-align: left;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 16px;
  background: transparent;
  border: none;
  color: var(--text);
  font-size: 1.05rem;
  font-weight: 850;
  cursor: pointer;
}

.faq-q:hover { background: rgba(255, 255, 255, 0.04); }

.chev {
  width: 18px;
  height: 18px;
  transition: transform 220ms ease;
  opacity: 0.9;
}

.faq-item[data-open="true"] .chev { transform: rotate(180deg); }

.faq-a {
  padding: 0 16px;
  max-height: 0;
  overflow: hidden;
  transition: max-height 260ms ease;
}

.faq-a-inner {
  padding: 0 0 16px;
  color: rgba(255, 255, 255, 0.76);
  line-height: 1.6;
}

.faq-item[data-open="true"] .faq-a { max-height: 360px; }

/* CTA */
.cta {
  padding: 36px 0 54px;
}

.cta-box {
  border-radius: var(--radius-xl);
  background:
    radial-gradient(900px 500px at 60% 0%, rgba(229, 9, 20, 0.2), transparent 60%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.03));
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow: var(--shadow);
  padding: 26px;
}

.cta-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 14px;
}

.cta-title {
  font-family: var(--font-display);
  letter-spacing: 0.8px;
  margin: 0;
  font-size: clamp(1.5rem, 2.5vw, 2.1rem);
}

/* Footer */
.footer {
  padding: 34px 0 54px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  background: linear-gradient(180deg, rgba(0, 0, 0, 0.0), rgba(0, 0, 0, 0.55));
}

.footer-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 18px;
}

.footer-note {
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.96rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px 18px;
}

@media (max-width: 820px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 440px) {
  .footer-grid { grid-template-columns: 1fr; }
}

.footer a {
  color: rgba(255, 255, 255, 0.7);
  text-decoration: underline;
  text-decoration-color: rgba(255, 255, 255, 0.25);
  text-underline-offset: 3px;
}

.footer a:hover {
  color: rgba(255, 255, 255, 0.92);
  text-decoration-color: rgba(255, 255, 255, 0.5);
}

/* Page: Login */
.login-wrap {
  min-height: calc(100vh - 72px);
  display: grid;
  place-items: center;
  padding: 36px 0 54px;
}

.login-card {
  width: min(520px, 100%);
  border-radius: var(--radius-xl);
  border: 1px solid rgba(255, 255, 255, 0.12);
  background:
    radial-gradient(700px 380px at 20% 0%, rgba(229, 9, 20, 0.14), transparent 58%),
    rgba(255, 255, 255, 0.06);
  box-shadow: var(--shadow);
  padding: 22px;
}

.login-title {
  font-family: var(--font-display);
  letter-spacing: 0.8px;
  margin: 0;
  font-size: 2rem;
}

.login-sub {
  margin: 8px 0 0;
  color: rgba(255, 255, 255, 0.76);
}

.sep {
  height: 1px;
  background: rgba(255, 255, 255, 0.12);
  margin: 16px 0;
}

.help-toggle {
  width: 100%;
  text-align: left;
  background: transparent;
  border: none;
  color: rgba(255, 255, 255, 0.82);
  font-weight: 800;
  padding: 10px 0;
  cursor: pointer;
}

.help-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 240ms ease;
}

.help-panel[data-open="true"] { max-height: 220px; }

.help-panel-inner {
  padding: 4px 0 0;
  color: rgba(255, 255, 255, 0.72);
  line-height: 1.6;
}

.small-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 14px;
  margin-top: 8px;
}

.small-links a {
  color: rgba(255, 255, 255, 0.78);
  text-decoration: underline;
  text-decoration-color: rgba(255, 255, 255, 0.25);
  text-underline-offset: 3px;
}

.small-links a:hover {
  color: rgba(255, 255, 255, 0.92);
  text-decoration-color: rgba(255, 255, 255, 0.55);
}

.toast {
  position: fixed;
  left: 50%;
  bottom: 18px;
  transform: translateX(-50%);
  background: rgba(10, 10, 10, 0.75);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 999px;
  padding: 10px 14px;
  color: rgba(255, 255, 255, 0.92);
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.45);
  opacity: 0;
  pointer-events: none;
  transition: opacity 180ms ease, transform 180ms ease;
}

.toast[data-show="true"] {
  opacity: 1;
  transform: translateX(-50%) translateY(-4px);
}
