  border-color: rgba(255, 255, 255, 0.18);
}

/* Form */
.field {
  display: grid;
  gap: 8px;
}

.label {
  font-size: 0.9rem;
  color: var(--muted);
}

.input {
  width: 100%;
  background: rgba(0, 0, 0, 0.35);
  color: var(--text);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 14px;
  padding: 14px 14px;
  transition: border-color 160ms ease, background 160ms ease;
}

.input::placeholder { color: rgba(255, 255, 255, 0.45); }

.input:focus {
  outline: none;
  border-color: rgba(229, 9, 20, 0.55);
  background: rgba(0, 0, 0, 0.5);
}

.input-error {
  border-color: rgba(255, 77, 77, 0.7);
}

.hint {
  color: rgba(255, 120, 120, 0.85);
  font-size: 0.9rem;
}

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 30;
  background: linear-gradient(180deg, rgba(20, 20, 20, 0.92), rgba(20, 20, 20, 0.65));
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 0;
  gap: 14px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 900;
  letter-spacing: 0.2px;
}

.brand-mark {
  width: 26px;
  height: 18px;
  border-radius: 6px;
  background: linear-gradient(180deg, var(--brand-2), var(--brand));
  box-shadow: 0 12px 26px rgba(229, 9, 20, 0.22);
  position: relative;
}

.brand-mark::after {
  content: "";
  position: absolute;
  left: 6px;
  top: 4px;
  width: 0;
  height: 0;
  border-top: 5px solid transparent;
  border-bottom: 5px solid transparent;
  border-left: 8px solid rgba(255, 255, 255, 0.92);
}

.brand-name {
  font-family: var(--font-display);
  font-size: 1.55rem;
  letter-spacing: 1px;
}

.nav-actions {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.select {
  appearance: none;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 999px;
  padding: 10px 34px 10px 12px;
  color: var(--text);
  font-weight: 650;
  cursor: pointer;
}

.select-wrap {
  position: relative;
}

.select-wrap::after {
  content: "▾";
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(255, 255, 255, 0.75);
  pointer-events: none;
  font-size: 0.9rem;
}

@media (max-width: 560px) {
  .select-wrap { display: none; }
