/* Hero */
.hero {
  padding: 54px 0 28px;
}

.hero-shell {
  position: relative;
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(900px 500px at 70% 30%, rgba(229, 9, 20, 0.22), transparent 58%),
