  background-position: center;
  filter: saturate(1.05) contrast(1.05);
}

.hero-grid {
  position: relative;
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 22px;
  padding: 34px;
  align-items: center;
}

@media (max-width: 920px) {
  .hero-grid { grid-template-columns: 1fr; padding: 24px; }
}

.hero-kicker {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: rgba(0, 0, 0, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.12);
  padding: 8px 12px;
  border-radius: 999px;
  color: rgba(255, 255, 255, 0.88);
  width: fit-content;
}

.pill-dot {
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: var(--brand);
  box-shadow: 0 0 0 4px rgba(229, 9, 20, 0.15);
}

.hero h1 {
  font-family: var(--font-display);
  font-size: clamp(2.25rem, 5vw, 4.1rem);
  line-height: 0.95;
  letter-spacing: 0.5px;
  margin: 14px 0 10px;
}

.hero-sub {
  font-size: 1.12rem;
  color: rgba(255, 255, 255, 0.86);
  margin: 0 0 12px;
}

.hero-prompt {
  color: rgba(255, 255, 255, 0.8);
  margin: 0 0 14px;
}

.hero-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  align-items: center;
}

@media (max-width: 520px) {
  .hero-form { grid-template-columns: 1fr; }
  .hero-form .btn { width: 100%; }
}

.mini-note {
  margin-top: 10px;
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.92rem;
}

/* Right hero panel */
.hero-panel {
  background: rgba(0, 0, 0, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: var(--radius-lg);
  padding: 18px;
}

.hero-panel-title {
  font-weight: 800;
  letter-spacing: 0.2px;
  margin: 0 0 12px;
}

.stat-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px 14px;
  padding: 12px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.stat-row:first-of-type { border-top: none; padding-top: 0; }

.stat-label { color: rgba(255, 255, 255, 0.75); }
.stat-value { font-weight: 850; }

.badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(229, 9, 20, 0.12);
  border: 1px solid rgba(229, 9, 20, 0.28);
  padding: 8px 10px;
  border-radius: 999px;
  font-weight: 800;
  color: rgba(255, 255, 255, 0.92);
  margin-top: 12px;
}

