.section {
  padding: 42px 0;
}

.section-title {
  font-family: var(--font-display);
  letter-spacing: 0.8px;
  font-size: clamp(1.7rem, 3vw, 2.45rem);
  margin: 0 0 16px;
}

.section-sub {
  margin: 0 0 18px;
  color: var(--muted);
}

