.carousel {
  position: relative;
}

.carousel-viewport {
  display: flex;
  gap: 14px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding: 6px 2px 10px;
  scrollbar-width: none;
}

.carousel-viewport::-webkit-scrollbar { display: none; }

.card {
  scroll-snap-align: start;
  flex: 0 0 auto;
  width: 210px;
  border-radius: 18px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.06);
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.35);
  position: relative;
}

@media (max-width: 480px) {
  .card { width: 165px; }
}

.poster {
  height: 300px;
  background-size: cover;
  background-position: center;
  position: relative;
}

@media (max-width: 480px) {
  .poster { height: 248px; }
}

.poster::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(340px 220px at 50% 10%, rgba(255, 255, 255, 0.08), transparent 55%),
    linear-gradient(180deg, rgba(0, 0, 0, 0.05), rgba(0, 0, 0, 0.82));
}

.rank {
  position: absolute;
  left: 10px;
  bottom: 56px;
  font-family: var(--font-display);
  font-size: 5.2rem;
  letter-spacing: 1px;
  color: rgba(255, 255, 255, 0.16);
  text-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
  pointer-events: none;
}

.card-body {
  padding: 12px 12px 14px;
  position: relative;
}

.card-title {
  font-weight: 850;
  letter-spacing: 0.2px;
  margin: 0;
}

.card-meta {
  margin: 6px 0 0;
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.92rem;
}

.carousel-controls {
  position: absolute;
  right: 0;
  top: -54px;
  display: flex;
  gap: 10px;
}

.icon-btn {
  width: 44px;
  height: 44px;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(0, 0, 0, 0.35);
  color: rgba(255, 255, 255, 0.92);
  cursor: pointer;
  transition: transform 140ms ease, background 160ms ease, border-color 160ms ease;
}

.icon-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.2);
  transform: translateY(-1px);
}

.icon {
  width: 18px;
  height: 18px;
  display: block;
}

/* Features */
.features {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

@media (max-width: 980px) {
  .features { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 560px) {
  .features { grid-template-columns: 1fr; }
}

.feature-card {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.05));
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 18px;
  padding: 18px;
  min-height: 190px;
  position: relative;
  overflow: hidden;
}

.feature-card::before {
  content: "";
  position: absolute;
  inset: -40px -40px auto auto;
  width: 120px;
  height: 120px;
  background: radial-gradient(circle at 30% 30%, rgba(229, 9, 20, 0.26), transparent 60%);
  transform: rotate(20deg);
}

.feature-title {
  font-weight: 900;
  margin: 0 0 8px;
}

.feature-desc {
  margin: 0;
  color: rgba(255, 255, 255, 0.74);
  line-height: 1.5;
}

.feature-icon {
  position: absolute;
  right: 14px;
  bottom: 14px;
  width: 44px;
  height: 44px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: rgba(0, 0, 0, 0.38);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

/* FAQ */
.faq {
  display: grid;
  gap: 12px;
}

.faq-item {
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.06);
  overflow: clip;
}

.faq-q {
  width: 100%;
  text-align: left;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 16px;
  background: transparent;
  border: none;
  color: var(--text);
  font-size: 1.05rem;
  font-weight: 850;
  cursor: pointer;
}

.faq-q:hover { background: rgba(255, 255, 255, 0.04); }

.chev {
  width: 18px;
  height: 18px;
  transition: transform 220ms ease;
  opacity: 0.9;
}

.faq-item[data-open="true"] .chev { transform: rotate(180deg); }

.faq-a {
  padding: 0 16px;
  max-height: 0;
  overflow: hidden;
  transition: max-height 260ms ease;
}

.faq-a-inner {
  padding: 0 0 16px;
  color: rgba(255, 255, 255, 0.76);
  line-height: 1.6;
}

.faq-item[data-open="true"] .faq-a { max-height: 360px; }

/* CTA */
.cta {
  padding: 36px 0 54px;
}

.cta-box {
  border-radius: var(--radius-xl);
  background:
    radial-gradient(900px 500px at 60% 0%, rgba(229, 9, 20, 0.2), transparent 60%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.03));
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow: var(--shadow);
  padding: 26px;
}

.cta-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 14px;
}

.cta-title {
  font-family: var(--font-display);
  letter-spacing: 0.8px;
  margin: 0;
  font-size: clamp(1.5rem, 2.5vw, 2.1rem);
}

/* Footer */
.footer {
  padding: 34px 0 54px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  background: linear-gradient(180deg, rgba(0, 0, 0, 0.0), rgba(0, 0, 0, 0.55));
}

.footer-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 18px;
}

.footer-note {
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.96rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px 18px;
}

@media (max-width: 820px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 440px) {
  .footer-grid { grid-template-columns: 1fr; }
}

.footer a {
  color: rgba(255, 255, 255, 0.7);
  text-decoration: underline;
  text-decoration-color: rgba(255, 255, 255, 0.25);
  text-underline-offset: 3px;
}

.footer a:hover {
  color: rgba(255, 255, 255, 0.92);
  text-decoration-color: rgba(255, 255, 255, 0.5);
}

/* Page: Login */
.login-wrap {
  min-height: calc(100vh - 72px);
  display: grid;
  place-items: center;
  padding: 36px 0 54px;
}

.login-card {
  width: min(520px, 100%);
  border-radius: var(--radius-xl);
  border: 1px solid rgba(255, 255, 255, 0.12);
  background:
    radial-gradient(700px 380px at 20% 0%, rgba(229, 9, 20, 0.14), transparent 58%),
    rgba(255, 255, 255, 0.06);
  box-shadow: var(--shadow);
  padding: 22px;
}

.login-title {
  font-family: var(--font-display);
  letter-spacing: 0.8px;
  margin: 0;
  font-size: 2rem;
}

.login-sub {
  margin: 8px 0 0;
  color: rgba(255, 255, 255, 0.76);
}

.sep {
  height: 1px;
  background: rgba(255, 255, 255, 0.12);
  margin: 16px 0;
}

.help-toggle {
  width: 100%;
  text-align: left;
  background: transparent;
  border: none;
  color: rgba(255, 255, 255, 0.82);
  font-weight: 800;
  padding: 10px 0;
  cursor: pointer;
}

.help-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 240ms ease;
}

.help-panel[data-open="true"] { max-height: 220px; }

.help-panel-inner {
  padding: 4px 0 0;
  color: rgba(255, 255, 255, 0.72);
  line-height: 1.6;
}

.small-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 14px;
  margin-top: 8px;
}

.small-links a {
  color: rgba(255, 255, 255, 0.78);
  text-decoration: underline;
  text-decoration-color: rgba(255, 255, 255, 0.25);
  text-underline-offset: 3px;
}

.small-links a:hover {
  color: rgba(255, 255, 255, 0.92);
  text-decoration-color: rgba(255, 255, 255, 0.55);
}

.toast {
  position: fixed;
  left: 50%;
  bottom: 18px;
  transform: translateX(-50%);
  background: rgba(10, 10, 10, 0.75);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 999px;
  padding: 10px 14px;
  color: rgba(255, 255, 255, 0.92);
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.45);
  opacity: 0;
  pointer-events: none;
  transition: opacity 180ms ease, transform 180ms ease;
}

.toast[data-show="true"] {
  opacity: 1;
  transform: translateX(-50%) translateY(-4px);
}
